changeSet.sql:
DO $$
DECLARE
    r          record;
    v_max      bigint;
    v_last     bigint;
    v_called   boolean;
    v_forced   boolean;
    v_scanned  integer := 0;
    v_advanced integer := 0;
BEGIN
    FOR r IN
        SELECT s.oid      AS seq_oid,
               sn.nspname AS seq_schema,
               s.relname  AS seq_name,
               tn.nspname AS tbl_schema,
               t.relname  AS tbl_name,
               t.oid      AS tbl_oid,
               a.attname  AS col_name
          FROM pg_class s
          JOIN pg_namespace sn ON sn.oid = s.relnamespace
          JOIN pg_depend d     ON d.objid = s.oid
                              AND d.classid = 'pg_class'::regclass
                              AND d.refclassid = 'pg_class'::regclass
                              AND d.deptype IN ('a', 'i')
          JOIN pg_class t      ON t.oid = d.refobjid
          JOIN pg_namespace tn ON tn.oid = t.relnamespace
          JOIN pg_attribute a  ON a.attrelid = t.oid AND a.attnum = d.refobjsubid
         WHERE s.relkind = 'S'
           AND sn.nspname = 'nexus'
         ORDER BY t.relname, a.attname
    LOOP
        v_scanned := v_scanned + 1;

        SELECT relforcerowsecurity INTO v_forced FROM pg_class WHERE oid = r.tbl_oid;
        IF v_forced THEN
            EXECUTE format('ALTER TABLE %I.%I NO FORCE ROW LEVEL SECURITY', r.tbl_schema, r.tbl_name);
        END IF;
        EXECUTE format('SELECT max(%I) FROM %I.%I', r.col_name, r.tbl_schema, r.tbl_name) INTO v_max;
        IF v_forced THEN
            EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', r.tbl_schema, r.tbl_name);
        END IF;

        CONTINUE WHEN v_max IS NULL;

        EXECUTE format('SELECT last_value, is_called FROM %I.%I', r.seq_schema, r.seq_name)
           INTO v_last, v_called;
        -- The next nextval() returns last_value + 1 once the sequence has been
        -- called, and last_value itself before its first call.
        IF (v_called AND v_max > v_last) OR (NOT v_called AND v_max >= v_last) THEN
            PERFORM setval(r.seq_oid::regclass, v_max, true);
            v_advanced := v_advanced + 1;
            RAISE NOTICE 'hygiene-006-1: sequence %.% advanced to % (was last_value=% is_called=%) so the next %.%.% no longer collides',
                r.seq_schema, r.seq_name, v_max, v_last, v_called, r.tbl_schema, r.tbl_name, r.col_name;
        END IF;
    END LOOP;
    RAISE NOTICE 'hygiene-006-1: % sequence(s) scanned in schema nexus, % advanced past a lagging column max', v_scanned, v_advanced;
END $$;
